begin;
alter table public.characters drop constraint characters_deck_check;
alter table public.characters add constraint characters_deck_check check (jsonb_array_length(deck)=5 or (id='gunner' and deck='[1,2,3]'::jsonb) or (definition->>'deckType' in ('random','continuous') and jsonb_array_length(deck)=0));
insert into public.characters(id,display_name,deck,enabled,definition) values ('gunner','총잡이','[1,2,3]'::jsonb,true,'{"deckType":"fixed","role":"세 발의 탄환을 쏟아내는 사수","icon":"⌖","color":"#ffd08a","attackFx":"bullet","attackSfx":"sfx_attack_gunner","skill":{"id":"full_burst","name":"전탄발사","type":"hybrid","description":"손패는 1/2/3 세 장. 2사이클마다 1회 발동: 선택 카드가 중복되지 않으면 남은 손패를 모두 합산해 사용하고 새 사이클로 진입합니다. 중복 실패 시에도 사용 횟수는 소비됩니다."}}'::jsonb) on conflict(id) do update set display_name=excluded.display_name,deck=excluded.deck,definition=excluded.definition,enabled=true;
insert into public.shop_items(id,display_name,item_type,price,asset_key,target_character_id,is_default,gacha_enabled,sort_order) values ('gunner0','총잡이 기본 스킨','character_skin',0,'gunner0','gunner',true,false,150) on conflict(id) do update set enabled=true,is_default=true,gacha_enabled=false;
insert into public.characters(id,display_name,deck,enabled,definition) values ('fighter','무투가','[1,2,3,4,5]'::jsonb,true,'{"deckType":"fixed","role":"이어지는 권격으로 적을 압도하는 격투가","icon":"✊","color":"#ffac78","attackFx":"fist","attackSfx":"sfx_attack_fighter","skill":{"id":"combo","name":"연격","type":"passive","description":"몬스터 전투에서 직전 카드보다 높은 카드로 공격 성공 시 연격 +1(최대 3). 공격에 연격만큼 추가 피해. 중복 또는 몬스터 처치 시 중첩이 초기화됩니다."}}'::jsonb) on conflict(id) do update set display_name=excluded.display_name,deck=excluded.deck,definition=excluded.definition,enabled=true;
insert into public.shop_items(id,display_name,item_type,price,asset_key,target_character_id,is_default,gacha_enabled,sort_order) values ('fighter0','무투가 기본 스킨','character_skin',0,'fighter0','fighter',true,false,151) on conflict(id) do update set enabled=true,is_default=true,gacha_enabled=false;
commit;
